package com.securemcp.api;
import com.securemcp.authorization.AbacService; import com.securemcp.authorization.TenantContext; import com.securemcp.audit.AuditService;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/policies") public class AbacController {
 private final JdbcTemplate jdbc; private final AbacService abac; private final AuditService audit; private final TenantContext tenantContext;
 public AbacController(JdbcTemplate j,AbacService a,AuditService au,TenantContext tc){jdbc=j;abac=a;audit=au;tenantContext=tc;}
 public record PolicyRequest(@NotNull UUID tenantId,@NotBlank String policyKey,@NotBlank String effect,String subjectMatch,@NotBlank String actionMatch,@NotBlank String resourceMatch,Map<String,Object> requiredAttributes){}
 public record DecisionRequest(@NotNull UUID tenantId,@NotBlank String action,@NotBlank String resource){}
 @org.springframework.transaction.annotation.Transactional @PostMapping @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> create(@Valid @RequestBody PolicyRequest r){UUID tenant=tenantContext.requireTenant(r.tenantId());if(!List.of("ALLOW","DENY").contains(r.effect()))throw new IllegalArgumentException("effect must be ALLOW or DENY");UUID id=UUID.randomUUID();try{jdbc.update("insert into abac_policies(id,tenant_id,policy_key,effect,subject_match,action_match,resource_match,required_attributes) values (?,?,?,?,?,?,?,?::jsonb)",id,tenant,r.policyKey(),r.effect(),r.subjectMatch(),r.actionMatch(),r.resourceMatch(),new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(r.requiredAttributes()==null?Map.of():r.requiredAttributes()));}catch(Exception e){throw new IllegalArgumentException("Unable to create policy",e);}audit.record("authenticated-principal","abac.policy.create",id.toString(),"SUCCESS",Map.of("tenantId",tenant,"policyKey",r.policyKey()));return Map.of("id",id,"policyKey",r.policyKey());}
 @PostMapping("/decision") public Map<String,Object> decide(@Valid @RequestBody DecisionRequest r){UUID tenant=tenantContext.requireTenant(r.tenantId());var a=org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication();String subject=a==null?null:a.getName();var result=abac.decide(tenant,subject,r.action(),r.resource(),tenantContext.trustedAttributes());audit.record(subject,"abac.evaluate",r.resource(),Boolean.TRUE.equals(result.get("allowed"))?"ALLOW":"DENY",Map.of("tenantId",tenant,"action",r.action()));return result;}
}
